fn logical_or(x1: Vec<bool>, x2: Vec<bool>) -> Vec<bool> {
    // Precondition: the two input vectors must have the same length.
    assert_eq!(x1.len(), x2.len(), "Input vectors must be the same length");

    // Consume both vectors, zip them together, apply logical OR pointwise, and collect into a new Vec<bool>.
    x1.into_iter()
      .zip(x2.into_iter())
      .map(|(a, b)| a || b)
      .collect()
}

